 1  // Shared test helpers. Imported only by test files.
 2  import { ReactElement } from 'react';
 3  import { render, RenderOptions } from '@testing-library/react';
 4  import { AppProviders } from './App';
 5  
 6  // Screens render inside the app shell (theme + CssBaseline), as in production.
 7  export function renderScreen(ui: ReactElement, options?: RenderOptions) {
 8    return render(ui, { wrapper: AppProviders, ...options });
 9  }
10  
11  // Small presentational components render bare: they don't need the app shell.
12  export function renderComponent(ui: ReactElement, options?: RenderOptions) {
13    return render(ui, options);
14  }
15  
16  // jsdom has no matchMedia. This answers min-width / max-width queries for a
17  // fixed viewport width, which is all useMediaQuery needs.
18  export function mockViewportWidth(width: number) {
19    const matches = (query: string) =>
20      query.split(/\s+and\s+/).every((part) => {
21        const m = part.match(/\((min|max)-width:\s*([\d.]+)px\)/);
22        if (!m) return false;
23        const value = Number(m[2]);
24        return m[1] === 'min' ? width >= value : width <= value;
25      });
26    window.matchMedia = (query: string) =>
27      ({
28        matches: matches(query),
29        media: query,
30        onchange: null,
31        addListener: () => undefined,
32        removeListener: () => undefined,
33        addEventListener: () => undefined,
34        removeEventListener: () => undefined,
35        dispatchEvent: () => false,
36      } as MediaQueryList);
37  }

